import { cloneElement, useId, useRef } from 'react';
import type { ReactElement, RefObject } from 'react';
import './tooltip.css';

/**
 * B18 · Tooltip — built on the native popover attribute (top layer, no
 * z-index wars). Supplementary info only — never the sole carrier of a
 * label. 300ms delay; keyboard-focusable triggers show it on focus.
 */
export interface TooltipProps {
  /** The tooltip text. Supplementary — the trigger keeps its own label. */
  content: string;
  /** A single focusable element (button, a). Receives describedby. */
  children: ReactElement<Record<string, unknown>>;
  delay?: number;
}

export function Tooltip({ content, children, delay = 300 }: TooltipProps) {
  const id = useId();
  const tipRef: RefObject<HTMLDivElement | null> = useRef(null);
  const triggerRef: RefObject<HTMLElement | null> = useRef(null);
  const timer = useRef<number>(0);

  function place() {
    const tip = tipRef.current;
    const trigger = triggerRef.current;
    if (!tip || !trigger) return;
    tip.showPopover();
    const t = trigger.getBoundingClientRect();
    const r = tip.getBoundingClientRect();
    const left = Math.max(8, Math.min(t.left + t.width / 2 - r.width / 2, window.innerWidth - r.width - 8));
    const top = t.top - r.height - 6 < 8 ? t.bottom + 6 : t.top - r.height - 6;
    tip.style.left = `${left}px`;
    tip.style.top = `${top}px`;
  }

  function show() {
    window.clearTimeout(timer.current);
    timer.current = window.setTimeout(place, delay);
  }

  function showNow() {
    window.clearTimeout(timer.current);
    place();
  }

  function hide() {
    window.clearTimeout(timer.current);
    tipRef.current?.hidePopover();
  }

  const trigger = cloneElement(children, {
    'aria-describedby': id,
    ref: (node: HTMLElement | null) => {
      triggerRef.current = node;
    },
    onMouseEnter: show,
    onMouseLeave: hide,
    onFocus: showNow,
    onBlur: hide,
  });

  return (
    <>
      {trigger}
      <div ref={tipRef} id={id} className="sv-tooltip" popover="manual" role="tooltip">
        {content}
      </div>
    </>
  );
}

/* B18 · Tooltip — popover attribute, ink on white text */

@layer sv-components {
  .sv-tooltip {
    position: fixed;
    margin: 0;
    padding: 6px 10px;
    border: 0;
    border-radius: var(--sv-r);
    background: var(--sv-band);
    color: var(--sv-on-dark);
    font-family: var(--sv-font-ui);
    font-size: 11.5px;
    font-weight: 500;
    max-width: 260px;
  }

  /* ---- v0.9 · the tip arrives, and it only FADES -----------------

     No translate here, unlike B42 and B20, and the reason is in
     tooltip.tsx: the tip is placed by measuring its OWN
     `getBoundingClientRect()`, which — unlike `offsetWidth` — reports
     the box as transformed. It is only read for `width` and `height`,
     so a translate would in fact be harmless today; a fade is chosen
     anyway, because that is a fact about six lines of a sibling file
     and a component should not owe its entrance to one. An opacity
     step cannot be measured wrong.

     It is also the right move on the merits. B18 is a phrase that
     appears where the pointer already is, on a hover the reader did
     not commit to — a tip that travels 6px to reach a cursor that has
     not moved is the page pointing at itself. Not posture-gated (it
     answers an act), `--sv-t-fast`, and exit instant. */
  .sv-tooltip:popover-open {
    opacity: 1;
    transition: opacity var(--sv-t-fast) ease-out;
  }

  @starting-style {
    .sv-tooltip:popover-open {
      opacity: 0;
    }
  }
}
